class LLMAgent:
    def __init__(self, agent_id: int):
        self.agent_id = agent_id
        self._ctx_opponent_id = None
        self.defected = set()

    def decide(self) -> bool:
        if self._ctx_opponent_id in self.defected:
            return False
        return True

    def observe(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        if donor_id != self.agent_id and self._is_defection(donor_action):
            self.defected.add(donor_id)
        if recipient_id != self.agent_id and self._is_defection(recipient_action):
            self.defected.add(recipient_id)

    def _is_defection(self, action: str) -> bool:
        return action.strip().lower() in ("d", "defect", "defected")

class LLMAgent:
    def __init__(self, agent_id: int):
        self.agent_id = agent_id
        self._ctx_opponent_id = None
        self._defect_counts = {}
        self._coop_counts = {}

    def decide(self) -> bool:
        opponent = self._ctx_opponent_id
        if opponent is None:
            return True
        defects = self._defect_counts.get(opponent, 0)
        coops = self._coop_counts.get(opponent, 0)
        return defects <= coops

    def observe(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        self._record_action(donor_id, donor_action)
        self._record_action(recipient_id, recipient_action)

    def _record_action(self, agent_id: int, action: str) -> None:
        if action in ("D", "d", "defect", "Defect"):
            self._defect_counts[agent_id] = self._defect_counts.get(agent_id, 0) + 1
        else:
            self._coop_counts[agent_id] = self._coop_counts.get(agent_id, 0) + 1

class LLMAgent:
    def __init__(self, agent_id: int):
        self.agent_id = agent_id
        self._ctx_opponent_id = None
        self.last_opponent_action = {}

    def decide(self) -> bool:
        opponent = self._ctx_opponent_id
        if opponent is None:
            return True
        return self.last_opponent_action.get(opponent, 'C') == 'C'

    def observe(self, donor_id, donor_action, recipient_id, recipient_action) -> None:
        if donor_id == self.agent_id:
            opponent = recipient_id
            opponent_action = recipient_action
        elif recipient_id == self.agent_id:
            opponent = donor_id
            opponent_action = donor_action
        else:
            return
        self.last_opponent_action[opponent] = opponent_action

class LLMAgent:
    def __init__(self, agent_id: int):
        self.agent_id = agent_id
        self._ctx_opponent_id = None
        self.reputation = {}

    def decide(self) -> bool:
        opponent = self._ctx_opponent_id
        if opponent is None:
            return True
        return self.reputation.get(opponent, 0) >= 0

    def observe(
        self,
        donor_id: int,
        donor_action: str,
        recipient_id: int,
        recipient_action: str,
    ) -> None:
        self._record(donor_id, donor_action)
        self._record(recipient_id, recipient_action)

    def _record(self, agent_id: int, action: str) -> None:
        if agent_id == self.agent_id:
            return

        normalized = action.lower()
        if normalized in ("c", "cooperate", "coop"):
            delta = 1
        elif normalized in ("d", "defect", "def"):
            delta = -1
        else:
            delta = 0

        self.reputation[agent_id] = self.reputation.get(agent_id, 0) + delta

class LLMAgent:
    def __init__(self, agent_id: int) -> None:
        self.agent_id = agent_id
        self._ctx_opponent_id = None
        self.coop_counts = {}
        self.total_counts = {}

    def _cooperated(self, action: str) -> bool:
        if isinstance(action, bool):
            return action
        if isinstance(action, str):
            return action.strip().lower() in ("cooperate", "coop", "c", "true", "1", "yes")
        return bool(action)

    def decide(self) -> bool:
        opp = self._ctx_opponent_id
        if opp is None:
            return True
        total = self.total_counts.get(opp, 0)
        coop = self.coop_counts.get(opp, 0)
        if total < 3:
            return True
        return coop / total >= 0.5

    def observe(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        for agent_id, action in ((donor_id, donor_action), (recipient_id, recipient_action)):
            self.total_counts[agent_id] = self.total_counts.get(agent_id, 0) + 1
            if self._cooperated(action):
                self.coop_counts[agent_id] = self.coop_counts.get(agent_id, 0) + 1

