class LLMAgent:
    def __init__(self, agent_id: int) -> None:
        self.agent_id = agent_id
        self._ctx_opponent_id = None
        self.coop_counts = {}
        self.total_counts = {}

    def _is_cooperate(self, action: str) -> bool:
        if action is None:
            return True
        s = str(action).strip().lower()
        return s not in ("d", "defect", "defects", "0", "false", "no")

    def decide(self) -> bool:
        opp = self._ctx_opponent_id
        if opp is not None and opp in self.total_counts and self.total_counts[opp] > 0:
            coop_rate = self.coop_counts[opp] / self.total_counts[opp]
            return coop_rate >= 0.5
        return True

    def observe(
        self,
        donor_id: int,
        donor_action: str,
        recipient_id: int,
        recipient_action: str,
    ) -> None:
        for agent_id, action in ((donor_id, donor_action), (recipient_id, recipient_action)):
            if agent_id not in self.total_counts:
                self.total_counts[agent_id] = 0
                self.coop_counts[agent_id] = 0
            self.total_counts[agent_id] += 1
            if self._is_cooperate(action):
                self.coop_counts[agent_id] += 1

class LLMAgent:
    def __init__(self, agent_id: int) -> None:
        self.agent_id = agent_id
        self._ctx_opponent_id = None
        self.reputation = {}

    def _action_score(self, action: str) -> int:
        if action is None:
            return 0
        a = action.strip().lower()
        if a in ('c', 'cooperate', 'coop', 'true', '1', 'yes', 'y'):
            return 1
        if a in ('d', 'defect', 'def', 'false', '0', 'no', 'n'):
            return -1
        return 0

    def decide(self) -> bool:
        opp = self._ctx_opponent_id
        if opp is None:
            return True
        return self.reputation.get(opp, 0) >= 0

    def observe(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        if donor_id != self.agent_id:
            self.reputation[donor_id] = self.reputation.get(donor_id, 0) + self._action_score(donor_action)
        if recipient_id != self.agent_id:
            self.reputation[recipient_id] = self.reputation.get(recipient_id, 0) + self._action_score(recipient_action)

