        return str(action).lower().startswith("d")

    def _record_public_action(self, agent_id: int, action: str) -> None:
        if agent_id == self.agent_id:
            return
        stats = self.reputation.setdefault(agent_id, [0, 0])
        if self._is_defect(action):
            stats[1] += 1
        else:
            stats[0] += 1
        self.last_known_action[agent_id] = action

