        opponent = self._ctx_opponent_id
        if opponent is None:
            return True

        last_against_me = self.last_action_against_me.get(opponent)
        if last_against_me is not None and self._is_defect(last_against_me):
            return False

        stats = self.reputation.get(opponent)
        if stats is not None:
            total = stats[0] + stats[1]
            if total >= 3 and stats[1] > stats[0]:
                return False

        return True

    def observe(
        self,
        donor_id: int,
        donor_action: str,
        recipient_id: int,
        recipient_action: str,
    ) -> None:
