        opponent = self._ctx_opponent_id
        if opponent is None:
            return True
        return self.reputation.get(opponent, 0.0) >= 0.0

    def observe(
        self,
        donor_id: int,
        donor_action: str,
        recipient_id: int,
        recipient_action: str,
    ) -> None:
        donor_partner_rep = self.reputation.get(recipient_id, 0.0)
        recipient_partner_rep = self.reputation.get(donor_id, 0.0)

        if donor_id != self.agent_id:
            self._update(donor_id, self._evaluate(donor_action, donor_partner_rep))
        if recipient_id != self.agent_id:
            self._update(recipient_id, self._evaluate(recipient_action, recipient_partner_rep))

    def _evaluate(self, action: str, partner_rep: float) -> float:
        normalized = action.lower()
        if normalized in ("c", "cooperate", "coop"):
            return 1.0 if partner_rep >= 0.0 else -1.0
        if normalized in ("d", "defect", "def"):
            return -1.0 if partner_rep >= 0.0 else 1.0
        return 0.0

    def _update(self, agent_id: int, value: float) -> None:
        alpha = 0.5
        old = self.reputation.get(agent_id, 0.0)
        self.reputation[agent_id] = (1 - alpha) * old + alpha * value

